package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.jobs.GenerationFlowService.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
/** Actual original ready/body/first facts; body eligibility callback in the isolated locator fixture is explicit fictional. */
class ReportPeriodSupplementInputTest {
 boolean mysql(){return false;}
 ReportPeriodInputComponentTest h;
 void setup(){h=mysql()?new ReportPeriodInputComponentMySqlTest():new ReportPeriodInputComponentTest();h.setup();}
 @Test void LateActualDailyFirstBecomesEligibleOnlyAtTheNewOperationMicrosecond(){setup();var before=h.capture();h.h.h.f.jdbc.update("DELETE FROM jobs WHERE target_type='content_availability'");Instant first=ReportPeriodInputComponentTest.CUTOFF.plusNanos(1000);h.h.observe(first);assertTrue(h.capture().candidates().isEmpty());var next=h.service.captureSupplement(Stage.WEEKLY_REPORT,ReportPeriodInputComponentTest.LAST,first);assertEquals(1,next.candidates().size());assertEquals(6,next.missing().size());assertEquals(before.candidates().getFirst().evidence().bodyJson(),next.candidates().getFirst().evidence().bodyJson());assertEquals(first,next.dependencies().getFirst().completedAt());assertSame(next,h.rr(()->h.service.verifyObserved(next)));var cmd=new Prepare("report:weekly:"+ReportPeriodInputComponentTest.LAST,2,Stage.WEEKLY_REPORT,ReportPeriodInputComponentTest.LAST,null,next.dependencies(),List.of(),next.sourceProof().verifiedDependencyIds(),true,"a".repeat(64));var frozen=new ReportInputSnapshotService((c,t)->next.sourceProof()).freeze(cmd,first);assertTrue(frozen.hasContent());assertEquals("partial",frozen.coverageState());assertEquals(1,h.h.h.f.sends);}
 @Test void NaturalMonthKeepsEveryUnknownDayAndCurrentBodyCannotReplaceOriginal(){setup();var last=LocalDate.parse("2026-01-31");Instant cutoff=last.plusDays(1).atTime(5,0).atZone(ZoneId.of("Asia/Shanghai")).toInstant().plusSeconds(17).plusNanos(1000);var value=h.service.captureSupplement(Stage.MONTHLY_REPORT,last,cutoff);assertEquals(30,value.missing().size());assertEquals(1,value.candidates().size());assertTrue(value.sourceProof().noUpdateDates().isEmpty());h.h.h.f.jdbc.update("UPDATE contents SET body_json='{}',revision=99,input_job_id='fictional-current-input'");assertEquals(value.candidates(),h.service.captureSupplement(Stage.MONTHLY_REPORT,last,cutoff).candidates());h.valid=false;assertThrows(RuntimeException.class,()->h.rr(()->h.service.verifyObserved(value)));}
 @Test void AllOriginalPagesBudgetIssuerAndCanonicalPeriodRemainStrictAtNewCutoff(){setup();var producer=new DailyReportRootPagesTest();producer.h=h.h;for(int i=0;i<70;i++)producer.queued(i,DailyReportRootPagesTest.DAY,"fictional-explicit-period-pending-"+i);Instant cutoff=ReportPeriodInputComponentTest.CUTOFF.plusSeconds(3);var value=h.service.captureSupplement(Stage.WEEKLY_REPORT,ReportPeriodInputComponentTest.LAST,cutoff);assertEquals(71,value.originalRootCount());assertThrows(RuntimeException.class,()->h.create(1024).captureSupplement(Stage.WEEKLY_REPORT,ReportPeriodInputComponentTest.LAST,cutoff));assertThrows(RuntimeException.class,()->h.rr(()->h.create(32L*1024*1024).verifyObserved(value)));assertThrows(RuntimeException.class,()->h.service.captureSupplement(Stage.WEEKLY_REPORT,ReportPeriodInputComponentTest.LAST,cutoff.plusNanos(1)));assertThrows(RuntimeException.class,()->h.service.captureSupplement(Stage.WEEKLY_REPORT,ReportPeriodInputComponentTest.LAST,ReportPeriodInputComponentTest.CUTOFF.minusNanos(1000)));assertThrows(RuntimeException.class,()->h.rr(()->h.service.captureSupplement(Stage.WEEKLY_REPORT,ReportPeriodInputComponentTest.LAST,cutoff)));assertThrows(RuntimeException.class,()->h.service.capture(Stage.WEEKLY_REPORT,ReportPeriodInputComponentTest.LAST,cutoff));}
 @Test void RealProgramNoUpdateLateFirstCanCoverOnlyTheNewExplicitPeriod()throws Exception{var noUpdate=new ReportPeriodNoUpdateTest(){@Override boolean mysql(){return ReportPeriodSupplementInputTest.this.mysql();}};noUpdate.setup();noUpdate.h.clock=Clock.fixed(noUpdate.cutoff.plusNanos(1000),ZoneOffset.UTC);noUpdate.h.compose();var available=noUpdate.h.service.observe(noUpdate.h.f.f.scope);var base=noUpdate.h.f.f.f.data.nativeData().fixture().f();var actual=new ReportPeriodInputComponentService(base.source,new ReportOriginalCompletionService(base.source,base.tx),v->{throw new AssertionError("program no update must not ask body eligibility");},noUpdate.h.service,base.tx);assertTrue(actual.capture(Stage.WEEKLY_REPORT,noUpdate.last,noUpdate.cutoff).sourceProof().noUpdateDates().isEmpty());var value=actual.captureSupplement(Stage.WEEKLY_REPORT,noUpdate.last,available.availableAt());assertEquals(List.of(noUpdate.h.f.f.scope.day()),value.sourceProof().noUpdateDates());assertEquals(6,value.missing().size());assertTrue(value.candidates().isEmpty());assertTrue(value.dependencies().isEmpty());assertTrue(value.referenceTargets().isEmpty());assertSame(value,noUpdate.h.f.f.f.rr(()->actual.verifyObserved(value)));assertEquals(2,base.sends);}
}
